def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: dict with days, seconds, microseconds
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        days = value.days
        seconds = value.seconds
        microseconds = value.microseconds
    except AttributeError as exc:
        raise TypeError("value must be a datetime.timedelta instance") from exc
    except Exception as exc:
        raise RuntimeError("Unexpected error while dehydrating timedelta") from exc
    return {"days": days, "seconds": seconds, "microseconds": microseconds}

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: The time value to dehydrate.
    :type value: datetime.time
    :return: A string representation of the time in ISO 8601 format,
             or ``None`` if the input is ``None``.
    :raises TypeError: If ``value`` is not a ``datetime.time`` instance.
    """
    # Allow ``None`` to be passed through unchanged
    if value is None:
        return None

    # Import datetime only when needed to avoid top‑level imports
    try:
        import datetime
    except Exception as exc:
        raise TypeError("datetime module is required for dehydrate_time") from exc

    if not isinstance(value, datetime.time):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

    # ``datetime.time.isoformat`` handles timezone information and microseconds
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict or None
    """
    try:
        if value is None:
            return None

        # If value is already a dict with numeric coordinates
        if isinstance(value, dict):
            # Ensure keys are numeric
            if all(k in ("x", "y", "z") for k in value.keys()):
                return {k: float(v) for k, v in value.items() if k in ("x", "y", "z")}
            else:
                raise TypeError("Dictionary keys must be 'x', 'y', or 'z'")

        # If value is a tuple or list of length 2 or 3
        if isinstance(value, (tuple, list)):
            if len(value) not in (2, 3):
                raise TypeError("Tuple/list must have length 2 or 3")
            coords = [float(v) for v in value]
            return {"x": coords[0], "y": coords[1]} if len(coords) == 2 else {"x": coords[0], "y": coords[1], "z": coords[2]}

        # If value has attributes x, y, (optional z)
        attrs = {}
        for attr in ("x", "y", "z"):
            if hasattr(value, attr):
                attrs[attr] = getattr(value, attr)
        if "x" in attrs and "y" in attrs:
            return {k: float(v) for k, v in attrs.items()}
        else:
            raise TypeError("Object does not have required 'x' and 'y' attributes")

    except Exception as exc:
        # Log or re-raise with context if needed
        raise TypeError(f"Cannot dehydrate point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve keys from the primary data container
        data = getattr(self, "_data", None)
        if isinstance(data, dict):
            return list(data.keys())

        # Fallback to an alternative attribute that might hold the record
        data = getattr(self, "record", None)
        if isinstance(data, dict):
            return list(data.keys())

        # As a last resort, return the public attribute names of the instance
        return [k for k in self.__dict__ if not k.startswith("_")]
    except Exception:
        # If any unexpected error occurs, return an empty list
        return []

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Determine the container attribute to search
    if hasattr(self, "_items"):
        container = self._items
    elif hasattr(self, "items"):
        container = self.items
    elif hasattr(self, "data"):
        container = self.data
    else:
        raise AttributeError("No suitable container attribute found for index lookup.")

    try:
        # If the container is a dict, search its keys
        if isinstance(container, dict):
            return list(container.keys()).index(key)
        # Otherwise, assume it supports the list index method
        return container.index(key)
    except ValueError:
        raise ValueError(f"Key {key!r} not found in the collection.")
    except AttributeError:
        raise AttributeError("The container does not support indexing.")
    except Exception as exc:
        raise RuntimeError(f"An unexpected error occurred while finding index: {exc}") from exc

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying data structure
    data = getattr(self, 'data', None)
    if data is None:
        data = getattr(self, '_data', None)
    if data is None:
        raise AttributeError("Record data not found in the object")
    if not isinstance(data, dict):
        raise TypeError("Record data must be a dictionary")
    items = list(data.items())
    if not keys:
        return [v for _, v in items]
    result = []
    for key in keys:
        try:
            if isinstance(key, int):
                idx = key
                if idx < 0:
                    idx = len(items) + idx
                if idx < 0 or idx >= len(items):
                    raise ValueError(f"Index {key} out of range")
                result.append(items[idx][1])
            else:
                result.append(data[key])
        except KeyError:
            raise ValueError(f"Key {key} not found in record")
        except TypeError:
            raise ValueError(f"Invalid key type: {type(key).__name__}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate parameters
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if n < -1:
        raise ValueError("n must be -1 (ALL) or a non‑negative integer")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an integer, got {type(qid).__name__}")
    if qid < -1:
        raise ValueError("qid must be -1 (last query) or a non‑negative integer")

    # Ensure hooks are dictionaries
    dehydration_hooks = dehydration_hooks or {}
    if not isinstance(dehydration_hooks, dict):
        raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
    hydration_hooks = hydration_hooks or {}
    if not isinstance(hydration_hooks, dict):
        raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")

    # Pack the DISCARD message payload
    try:
        payload = packstream.pack([n, qid], dehydration_hooks)
    except Exception as exc:
        raise RuntimeError(f"Failed to pack DISCARD message: {exc}") from exc

    # Append the message to the output queue
    try:
        self._output_queue.append((0x0C, payload))
    except AttributeError as exc:
        raise AttributeError("self._output_queue is not defined") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to append DISCARD message to output queue: {exc}") from exc

    # Return a Response object with the provided handlers and hydration hooks
    try:
        return Response(self, handlers, hydration_hooks)
    except Exception as exc:
        raise RuntimeError(f"Failed to create Response object: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is not None and mode not in ("READ", "WRITE"):
            raise ValueError(f"Invalid mode '{mode}'. Expected 'READ' or 'WRITE'.")

        # Validate bookmarks
        if bookmarks is not None:
            try:
                iter(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable of strings.")
            for bm in bookmarks:
                if not isinstance(bm, str):
                    raise ValueError("Each bookmark must be a string.")

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary.")

        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number (int or float).")

        # Validate db and imp_user
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string.")
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string.")

        # Validate dehydration_hooks and hydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dictionary.")
            for key, func in dehydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("Keys of dehydration_hooks must be types.")
                if not callable(func):
                    raise ValueError("Values of dehydration_hooks must be callables.")
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dictionary.")
            for key, func in hydration_hooks.items():
                if not isinstance(key, type):
                    raise ValueError("Keys of hydration_hooks must be types.")
                if not callable(func):
                    raise ValueError("Values of hydration_hooks must be callables.")

        # Store hooks if provided
        if dehydration_hooks is not None:
            self._dehydration_hooks = dehydration_hooks
        if hydration_hooks is not None:
            self._hydration_hooks = hydration_hooks

        # Build parameters dictionary
        params = {}
        if mode is not None:
            params["mode"] = mode
        if bookmarks is not None:
            params["bookmarks"] = list(bookmarks)
        if metadata is not None:
            params["metadata"] = metadata
        if timeout is not None:
            params["timeout"] = timeout
        if db is not None:
            params["db"] = db
        if imp_user is not None:
            params["imp_user"] = imp_user

        # Append BEGIN message to output queue
        message = {"type": "BEGIN", "params": params}
        self._output_queue.append(message)

        # Return a Response object with the provided handlers
        return Response(self, **handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the name
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not name:
        raise ValueError("name cannot be empty")
    if not name.isidentifier():
        raise ValueError(f"name '{name}' is not a valid identifier")

    # Validate fields
    if not isinstance(fields, dict):
        raise TypeError("fields must be a dict")
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare the class dictionary
    class_dict = {"__module__": __name__}
    for key, value in fields.items():
        if not isinstance(key, str):
            raise TypeError(f"field name {key!r} must be a string")
        class_dict[key] = value
    class_dict["srid_map"] = srid_map

    # Create the subclass
    try:
        cls = type(name, (Point,), class_dict)
    except NameError as exc:
        raise NameError("Base class 'Point' is not defined") from exc

    return cls

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise TypeError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise TypeError("ttl must be a non-negative number")
    if not callable(timer):
        raise TypeError("timer must be callable")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}

        def make_key(args, kwargs):
            # Base key from positional and keyword arguments
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include type information for positional arguments
                new_key = []
                for a in args:
                    new_key.append((a, type(a)))
                # Include keyword argument names and values with type of value
                for k, v in sorted(kwargs.items()):
                    new_key.append((k, v, type(v)))
                return tuple(new_key)
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, expire = entry
                if now < expire:
                    # Move to end to mark as recently used
                    cache.pop(key)
                    cache[key] = (value, expire)
                    return value
                else:
                    # Expired entry
                    cache.pop(key, None)
            # Compute new value
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise
            expire = now + ttl
            cache[key] = (result, expire)
            # Enforce maxsize
            if len(cache) > maxsize:
                oldest_key = next(iter(cache))
                cache.pop(oldest_key, None)
            return result

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    value = self[key]
    del self[key]
    return key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except Exception as exc:
        raise TypeError(f"Error in setdefault with key {key!r}: {exc}") from exc

def get(self, key, default=None):
    """
    Return the value for key if key is in the dictionary, else default.
    Handles missing keys and non-mapping self gracefully.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except (TypeError, AttributeError):
        # self is not subscriptable or key unhashable
        return default

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        # Validate input
        if not isinstance(file_name, str) or not file_name:
            return False
        try:
            import os
            return os.path.isfile(file_name)
        except Exception:
            return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        name = self.__class__.__name__
        if name.endswith('Py'):
            return name[:-2]
        if name.endswith('Fallback'):
            return name[:-8]
        return name
    except Exception as exc:
        raise RuntimeError("Unable to determine target class") from exc

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        decl = getattr(object, "__provides__", None)
        if decl is None:
            # Return an empty declaration if the object does not provide any interfaces
            return {}
        return decl
    except Exception:
        # In case of any unexpected error, return an empty declaration
        return {}

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if not isinstance(output, list):
        raise TypeError("output must be a list or None")
    if sequence is None:
        raise TypeError("sequence cannot be None")
    try:
        iter(sequence)
    except TypeError:
        raise TypeError("sequence must be an iterable")
    for item in sequence:
        # Treat tuples as implements specs and keep them as a single item
        if isinstance(item, tuple):
            output.append(item)
            continue
        # Individual interfaces: strings or types
        if isinstance(item, (str, type)):
            output.append(item)
            continue
        # Declarions: objects that expose an 'args' attribute which is iterable
        if hasattr(item, "args"):
            args = getattr(item, "args")
            if isinstance(args, (list, tuple)):
                output.extend(args)
                continue
        # Lists (or other iterables) are expanded
        if isinstance(item, list):
            output.extend(item)
            continue
        # General iterable (excluding strings and types)
        if hasattr(item, "__iter__") and not isinstance(item, (str, type)):
            try:
                for sub in item:
                    output.append(sub)
                continue
            except TypeError:
                pass
        # If we reach here, the item type is unsupported
        raise TypeError(f"Unsupported argument type: {type(item)}")
    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
    except Exception:
        # If the required function is unavailable or raises an error,
        # assume optimizations are not required.
        return False
    return not bool(required)

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context
        try:
            self._context = {}
        except AttributeError:
            # If the histogram does not have a _context attribute, ignore
            pass

        # Reinitialize bins
        try:
            if hasattr(self, "_initial_value") and self._initial_value is not None:
                # If bins already exist, preserve their length
                if hasattr(self, "_bins") and self._bins is not None:
                    self._bins = [self._initial_value] * len(self._bins)
                else:
                    # No existing bins, create a single bin with the initial value
                    self._bins = [self._initial_value]
            elif hasattr(self, "_make_bins") and callable(self._make_bins):
                self._bins = self._make_bins()
            else:
                # No initial value or make_bins function provided; leave bins unchanged
                pass
        except Exception as exc:
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []
    if header is not None:
        lines.append(header)

    try:
        # Retrieve points iterable; raise if not present
        points = getattr(self, "points", None)
        if points is None:
            raise AttributeError("Graph object has no 'points' attribute")

        for point in points:
            # Expect point to be (coord, value) or just coord
            if isinstance(point, (list, tuple)):
                if len(point) == 2:
                    coord, value = point
                else:
                    coord = point
                    value = None
            else:
                coord = point
                value = None

            # Convert coordinate to string
            if isinstance(coord, (list, tuple)):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)

            # Convert value to string
            if value is None:
                value_str = ""
            else:
                if isinstance(value, (str, bytes)):
                    value_str = str(value)
                elif hasattr(value, "__iter__"):
                    # Avoid treating strings as iterables
                    value_str = separator.join(map(str, value))
                else:
                    value_str = str(value)

            # Build line
            line = coord_str
            if value_str:
                line += separator + value_str
            lines.append(line)

    except Exception as exc:
        raise RuntimeError(f"Failed to convert graph to CSV: {exc}") from exc

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    if not coord_name:
        raise ValueError("coord_name cannot be empty")

    # Retrieve the error indices mapping
    try:
        indices = self._err_indices[coord_name]
    except AttributeError:
        raise AttributeError("The object does not have a '_err_indices' attribute")
    except KeyError:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'")

    # Ensure the returned value is a list (or a copy of the original iterable)
    if isinstance(indices, (list, tuple)):
        return list(indices)
    try:
        return list(indices)
    except TypeError:
        raise TypeError(f"Error indices for coordinate '{coord_name}' are not iterable")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to lists to allow len() and indexing
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    # Basic length checks
    if len(edges_list) < 2:
        if len(bins_list) == 0:
            return 0.0
        raise ValueError("edges must contain at least two elements for non-empty bins")

    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Compute bin widths and validate edges
    widths = []
    for i in range(len(bins_list)):
        try:
            left = float(edges_list[i])
            right = float(edges_list[i + 1])
        except Exception as exc:
            raise TypeError("edges must contain numeric values") from exc
        width = right - left
        if width <= 0:
            raise ValueError("edges must be strictly increasing")
        widths.append(width)

    # Compute integral
    total = 0.0
    for b, w in zip(bins_list, widths):
        try:
            total += float(b) * w
        except Exception as exc:
            raise TypeError("bins must contain numeric values") from exc

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq itself is a FillRequest, return True
        if isinstance(seq, FillRequest):
            return True

        # If seq is a Source, it's not a FillRequestSeq
        if isinstance(seq, Source):
            return False

        # If seq is iterable, check its elements
        if isinstance(seq, (list, tuple, set)):
            # If any element is a Source, reject
            if any(isinstance(item, Source) for item in seq):
                return False
            # Return True if any element is a FillRequest
            return any(isinstance(item, FillRequest) for item in seq)

        # For non-iterable types, return False
        return False
    except NameError:
        # If FillRequest or Source classes are not defined, cannot determine
        return False
    except Exception:
        # Any other unexpected error results in False
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight_val = float(weight)
    except Exception:
        raise TypeError("weight must be a numeric value")
    # Get edges
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object has no 'edges' attribute")
    edges = self.edges
    # Validate edges
    if not hasattr(edges, "__len__") or len(edges) < 2:
        raise ValueError("Histogram edges must be a sequence with at least two elements")
    # Get bin storage
    if hasattr(self, "_counts"):
        bins = self._counts
    elif hasattr(self, "bins"):
        bins = self.bins
    else:
        raise AttributeError("Histogram object has no bin storage attribute")
    # Validate bins length
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins does not match number of edges")
    # Prepare coordinates iterable
    if isinstance(coord, (str, bytes)):
        coords_iter = [coord]
    else:
        try:
            iter(coord)
            coords_iter = coord
        except TypeError:
            coords_iter = [coord]
    # Iterate over coordinates
    for c in coords_iter:
        # Validate coordinate numeric
        try:
            c_val = float(c)
        except Exception:
            continue  # ignore non-numeric coordinate
        # Check bounds
        if c_val < edges[0] or c_val >= edges[-1]:
            continue
        # Find bin index
        bin_index = None
        for i in range(len(edges) - 1):
            if edges[i] <= c_val < edges[i + 1]:
                bin_index = i
                break
        if bin_index is None:
            continue
        # Increment bin
        try:
            bins[bin_index] = bins[bin_index] + weight_val
        except Exception as e:
            raise RuntimeError(f"Failed to increment bin {bin_index}: {e}")
    return

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Simple regex patterns for demonstration purposes.
    # In real usage these should be replaced with the actual Kubernetes label regexes.
    LABEL_KEY_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    LABEL_VALUE_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'labels must be a dict'}])

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            key_str = key.decode('utf-8') if isinstance(key, bytes) else key
            if not LABEL_KEY_REGEX.match(key_str):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value
        # Treat lists/tuples as a single value (not iterated over)
        if isinstance(value, (list, tuple)):
            # The value itself is not a string/bytes, so error
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                value_str = value.decode('utf-8') if isinstance(value, bytes) else value
                if not LABEL_VALUE_REGEX.match(value_str):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                value_str = value.decode('utf-8') if isinstance(value, bytes) else value
                if not LABEL_VALUE_REGEX.match(value_str):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, str):
        raise ValueError("ValidationError: value must be a string")
    try:
        re_mod = __import__('re')
    except Exception as exc:
        raise ValueError("ValidationError: regex module not available") from exc
    pattern = r'^[A-Za-z0-9]+$'
    if not re_mod.match(pattern, value):
        raise ValueError("ValidationError: value does not match the required pattern")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("The application object does not have a 'spec' attribute.")
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("The application spec does not have a 'manifest' attribute.")
    if not isinstance(manifest, list):
        raise TypeError("The 'manifest' attribute must be a list of Kubernetes resources.")

    # Custom observer schemas, if any
    custom_schema = getattr(spec, "observer_schema", {})
    if custom_schema is None:
        custom_schema = {}
    if not isinstance(custom_schema, dict):
        # If the custom schema is not a dict, ignore it
        custom_schema = {}

    default_schema = {}
    for resource in manifest:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        kind = resource.get("kind")
        if not kind:
            # Skip resources without a kind
            continue
        # Skip kinds that already have a custom observer schema
        if kind in custom_schema:
            continue
        # Generate a minimal default observer schema.
        # Here we simply provide an empty schema; this can be extended
        # with more sophisticated defaults if needed.
        default_schema[kind] = {}
    return default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        # Accept pathlib.Path or string
        try:
            from pathlib import Path
        except Exception:
            return False
        p = Path(path)
        if not p.exists() or not p.is_dir():
            return False

        # Check .ocfl_version file
        version_file = p / ".ocfl_version"
        if not version_file.is_file():
            return False
        try:
            version_text = version_file.read_text().strip()
            if not version_text.isdigit():
                return False
        except Exception:
            return False

        # Check .ocfl_root file
        root_file = p / ".ocfl_root"
        if not root_file.is_file():
            return False
        try:
            root_path = root_file.read_text().strip()
            if not root_path:
                return False
        except Exception:
            return False

        # Check objects directory
        objects_dir = p / "objects"
        if not objects_dir.is_dir():
            return False

        # Ensure at least one version directory exists
        version_dirs = [d for d in objects_dir.iterdir() if d.is_dir()]
        if not version_dirs:
            return False

        # Each version directory should contain a manifest.json
        for vd in version_dirs:
            manifest = vd / "manifest.json"
            if not manifest.is_file():
                return False

        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        # Ensure prefix is a string
        prefix = str(prefix) if prefix is not None else ''
        # Determine status representation
        if hasattr(self, 'status'):
            status = self.status
        elif hasattr(self, 'valid'):
            status = 'valid' if self.valid else 'invalid'
        else:
            status = str(self)
        # Convert status to string if necessary
        status = str(status)
        return f"{prefix}{status}"
    except Exception as e:
        # Fallback in case of unexpected errors
        return f"{prefix}Error retrieving status: {e}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Ensure prefix is a string
        if prefix is None:
            prefix = ''
        if not isinstance(prefix, str):
            prefix = str(prefix)
        # Retrieve log from common attribute names
        log = getattr(self, "_log", None)
        if log is None:
            log = getattr(self, "log", None)
        if log is None:
            return ''
        # If log is a string, treat as single line
        if isinstance(log, str):
            lines = [log]
        else:
            # Try to iterate over log
            try:
                lines = [str(item) for item in log]
            except Exception:
                # Fallback: convert log to string
                lines = [str(log)]
        # Apply prefix to each line
        if prefix:
            lines = [f"{prefix}{line}" for line in lines]
        return "\n".join(lines)
    except Exception as exc:
        # Return a concise error message
        return f"Error generating status string: {exc}"

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks
    if not isinstance(extract_spec_version, bool):
        raise TypeError("extract_spec_version must be a boolean")
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Mapping from inventory type to spec version
    type_to_spec = {
        "typeA": "1.0",
        "typeB": "2.0",
        "typeC": "3.0",
    }
    allowed_specs = {"1.0", "2.0", "3.0"}

    # Determine spec version to use
    spec_version = None
    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str) and inv_type in type_to_spec:
            spec_version = type_to_spec[inv_type]
        else:
            spec_version = getattr(self, "spec_version", None)
    else:
        spec_version = getattr(self, "spec_version", None)

    if spec_version is None:
        raise ValueError("spec_version could not be determined")
    if spec_version not in allowed_specs:
        raise ValueError(f"Unsupported spec_version: {spec_version}")

    # Validate required top-level fields
    name = inventory.get("name")
    if not isinstance(name, str) or not name:
        raise ValueError("inventory must have a non-empty 'name' string")

    items = inventory.get("items")
    if not isinstance(items, list):
        raise TypeError("inventory 'items' must be a list")
    if not items:
        raise ValueError("inventory 'items' list cannot be empty")

    # Validate each item
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"item at index {idx} must be a dict")

        item_id = item.get("id")
        if not isinstance(item_id, str) or not item_id:
            raise ValueError(f"item at index {idx} must have a non-empty 'id' string")

        quantity = item.get("quantity")
        if not isinstance(quantity, int):
            raise TypeError(f"item at index {idx} 'quantity' must be an int")
        if quantity < 0:
            raise ValueError(f"item at index {idx} 'quantity' cannot be negative")
        if spec_version == "2.0" and quantity == 0:
            raise ValueError(f"item at index {idx} 'quantity' must be > 0 for spec_version 2.0")

        if spec_version == "3.0":
            price = item.get("price")
            if price is None:
                raise ValueError(f"item at index {idx} must have 'price' for spec_version 3.0")
            if not isinstance(price, (int, float)):
                raise TypeError(f"item at index {idx} 'price' must be a number")
            if price < 0:
                raise ValueError(f"item at index {idx} 'price' cannot be negative")

    # Optional fields based on spec version
    if spec_version == "1.0":
        description = inventory.get("description")
        if description is not None and not isinstance(description, str):
            raise TypeError("inventory 'description' must be a string if provided")

    # If all checks pass
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Validate inputs
        if manifest_files is None:
            raise TypeError("manifest_files cannot be None")
        if digests_used is None:
            raise TypeError("digests_used cannot be None")

        try:
            iter(manifest_files)
        except TypeError:
            raise TypeError("manifest_files must be an iterable of manifest entries")

        try:
            iter(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digests")

        # Extract digests from manifest
        digests_in_manifest = set()
        for entry in manifest_files:
            if entry is None:
                continue
            # If entry is a dict with a 'digest' key
            if isinstance(entry, dict):
                digest = entry.get("digest")
                if digest is not None:
                    digests_in_manifest.add(digest)
                continue
            # If entry is a tuple/list with at least two elements
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                digest = entry[1]
                if digest is not None:
                    digests_in_manifest.add(digest)
                continue
            # If entry is a string, treat it as a digest (unlikely but safe)
            if isinstance(entry, str):
                digests_in_manifest.add(entry)
                continue
            # Unsupported entry type; ignore or raise warning
            # For safety, we ignore unsupported types

        # Convert digests_used to a set
        digests_used_set = set(digests_used)

        # Check for missing digests in the manifest
        missing_in_manifest = digests_used_set - digests_in_manifest
        if missing_in_manifest:
            raise ValueError(
                f"Missing digests in manifest: {sorted(missing_in_manifest)}"
            )

        # Check for unused digests in the manifest
        unused_in_manifest = digests_in_manifest - digests_used_set
        if unused_in_manifest:
            raise ValueError(
                f"Unused digests in manifest: {sorted(unused_in_manifest)}"
            )

        # All checks passed
        return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not hasattr(prior, 'version'):
        raise TypeError("prior must have a 'version' attribute")
    if not hasattr(self, 'version'):
        raise TypeError("self must have a 'version' attribute")

    # Ensure prior is actually an InventoryValidator instance if possible
    if not isinstance(prior, type(self)):
        # Allow subclasses
        if not isinstance(prior, type(self)):
            raise TypeError("prior must be an InventoryValidator instance")

    # Version comparison: prior must be older
    if prior.version >= self.version:
        raise ValueError(f"prior version ({prior.version}) must be less than current version ({self.version})")

    # Inventory comparison: prior inventory should be a subset of current inventory
    # We assume inventory is stored in an attribute named 'inventory' which can be a dict or set
    if not hasattr(prior, 'inventory') or not hasattr(self, 'inventory'):
        raise AttributeError("Both self and prior must have an 'inventory' attribute")

    # Determine the type of inventory
    curr_inv = self.inventory
    prior_inv = prior.inventory

    # If inventories are dicts, compare keys
    if isinstance(curr_inv, dict) and isinstance(prior_inv, dict):
        if not set(prior_inv.keys()).issubset(set(curr_inv.keys())):
            raise ValueError("prior inventory keys are not a subset of current inventory keys")
    # If inventories are sets or lists, compare elements
    elif isinstance(curr_inv, (set, list, tuple)) and isinstance(prior_inv, (set, list, tuple)):
        if not set(prior_inv).issubset(set(curr_inv)):
            raise ValueError("prior inventory items are not a subset of current inventory items")
    else:
        # Unsupported inventory types
        raise TypeError("Unsupported inventory type for comparison")

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping versions to state data")

    # Validate version presence
    if version not in inventory:
        raise ValueError(f"Version '{version}' not found in inventory")

    # Helper to sort version keys numerically if possible
    def _sort_key(v):
        try:
            return int(v)
        except Exception:
            return v

    # Sort versions
    sorted_versions = sorted(inventory.keys(), key=_sort_key)

    # Find index of target version
    try:
        target_index = sorted_versions.index(version)
    except ValueError:
        raise ValueError(f"Version '{version}' not found in inventory after sorting")

    # Prepare result mapping
    result = {}

    # Helper to add content files to a set
    def _add_content(target_set, content):
        if isinstance(content, (list, set, tuple)):
            for item in content:
                if isinstance(item, str):
                    target_set.add(item)
                else:
                    raise TypeError(f"Content file must be a string, got {type(item)}")
        elif isinstance(content, str):
            target_set.add(content)
        else:
            raise TypeError(f"Content file must be a string or iterable of strings, got {type(content)}")

    # Process target version
    target_state = inventory[version]
    if not isinstance(target_state, dict):
        raise TypeError("State data for a version must be a dict mapping logical paths to content files")

    for logical_path, content in target_state.items():
        result[logical_path] = set()
        _add_content(result[logical_path], content)

    # Include duplicates from later versions
    for later_version in sorted_versions[target_index + 1:]:
        later_state = inventory.get(later_version)
        if not isinstance(later_state, dict):
            continue  # skip invalid state entries
        for logical_path, content in later_state.items():
            if logical_path in result:
                _add_content(result[logical_path], content)

    return result

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError(f"Expected fixity to be a dict, got {type(fixity).__name__}")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError(f"Expected manifest_files to be a set, list, or tuple, got {type(manifest_files).__name__}")

    # Ensure required top-level key exists
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise TypeError(f"Expected 'files' to be a list, got {type(files).__name__}")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)

    # Validate each file entry
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise TypeError(f"File entry at index {idx} is not a dict, got {type(entry).__name__}")

        # Path must be present and a string
        path = entry.get('path')
        if path is None:
            raise ValueError(f"File entry at index {idx} missing required 'path' key")
        if not isinstance(path, str):
            raise TypeError(f"File entry at index {idx} has 'path' that is not a string, got {type(path).__name__}")

        # Ensure the path is in the manifest
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block is not present in the manifest")

        # Optional: check for hash and size if present
        if 'hash' in entry and not isinstance(entry['hash'], str):
            raise TypeError(f"File entry at index {idx} has 'hash' that is not a string")
        if 'size' in entry and not isinstance(entry['size'], (int, float)):
            raise TypeError(f"File entry at index {idx} has 'size' that is not a number")

    # If all checks pass, return True
    return True

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: identify basenames that have an XML file
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, ext = os.path.splitext(os.path.basename(name))
                if ext.lower() == '.xml':
                    xml_basenames.add(base)

            # Second pass: collect files belonging to those basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, _ = os.path.splitext(os.path.basename(name))
                if base in xml_basenames:
                    try:
                        content = zf.read(name)
                    except Exception as e:
                        raise RuntimeError(f"Error reading file '{name}' from zip: {e}") from e
                    if base not in packages:
                        packages[base] = {}
                    packages[base][name] = content
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file '{zip_path}': {e}") from e

    return packages

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not pubdate_xpaths:
        return None
    try:
        # Ensure pubdate_xpaths is iterable
        iter(pubdate_xpaths)
    except Exception:
        return None

    # Iterate over each XPath expression
    for xpath in pubdate_xpaths:
        try:
            # Execute the XPath on the node
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the result is an element, return its text content
                if hasattr(first, "text"):
                    return first.text
                # Otherwise return the result directly (string, number, etc.)
                return first
        except Exception:
            # Skip this XPath if it raises an error
            continue

    # No match found
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise TypeError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    seen = set()

    def _pretty(obj, level):
        # Detect recursion
        obj_id = id(obj)
        if obj_id in seen:
            return "<Recursion>"
        seen.add(obj_id)

        # Basic types
        if isinstance(obj, (str, int, float, bool, type(None))):
            result = repr(obj)
            if debug:
                result = f"{type(obj).__name__}({result})"
            return result

        # Dictionaries
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in obj.items():
                key_str = _pretty(k, level + 1)
                val_str = _pretty(v, level + 1)
                items.append(f"{' ' * (indent * (level + 1))}{key_str}: {val_str}")
            body = ",\n".join(items)
            result = f"{{\n{body}\n{' ' * (indent * level)}}}"
            if debug:
                result = f"dict{result}"
            return result

        # Lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                if isinstance(obj, list):
                    return "[]"
                if isinstance(obj, tuple):
                    return "()"
                return "set()"
            opening = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "set(["
            closing = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "])"
            items = []
            for item in obj:
                items.append(f"{' ' * (indent * (level + 1))}{_pretty(item, level + 1)}")
            body = ",\n".join(items)
            result = f"{opening}\n{body}\n{' ' * (indent * level)}{closing}"
            if debug:
                result = f"{type(obj).__name__}{result}"
            return result

        # Other objects: try to pretty print their __dict__
        if hasattr(obj, "__dict__"):
            return _pretty(obj.__dict__, level)

        # Fallback to repr
        result = repr(obj)
        if debug:
            result = f"{type(obj).__name__}({result})"
        return result

    try:
        return _pretty(self, 0)
    except Exception as e:
        # In case of unexpected errors, return a simple representation
        return f"<Error pretty printing: {e}>"

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise TypeError("hook must not be None")
    try:
        hash(hook)
    except Exception:
        raise TypeError(f"hook {hook!r} is not hashable and cannot be used as a key")
    # Ensure registry exists
    if not hasattr(self, "_registry") or not isinstance(self._registry, dict):
        self._registry = {}
    def decorator(func):
        if not callable(func):
            raise TypeError("listener must be a callable")
        try:
            listeners = self._registry.setdefault(hook, [])
            listeners.append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register listener for hook {hook!r}") from e
        return func
    return decorator

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default values
    default = {"version": "0.0.0", "full": "0.0.0", "dirty": False}
    try:
        # Try importlib.metadata (Python 3.8+)
        try:
            import importlib.metadata as importlib_metadata
        except Exception:
            importlib_metadata = None

        # Try pkg_resources as fallback
        try:
            import pkg_resources
        except Exception:
            pkg_resources = None

        # Determine distribution name from module/package name
        dist_name = None
        if __package__:
            dist_name = __package__
        else:
            dist_name = __name__.split(".")[0]

        # Get the base version
        if importlib_metadata:
            version = importlib_metadata.version(dist_name)
        elif pkg_resources:
            version = pkg_resources.get_distribution(dist_name).version
        else:
            return default

        # Try to get a full git description if available
        full = version
        dirty = False
        try:
            import subprocess, os
            # Determine the directory of this file if possible
            cwd = os.path.dirname(__file__) if "__file__" in globals() else None
            if cwd:
                git_describe = subprocess.check_output(
                    ["git", "describe", "--tags", "--dirty", "--always"],
                    cwd=cwd,
                    stderr=subprocess.DEVNULL,
                    text=True,
                ).strip()
                full = git_describe
                dirty = git_describe.endswith("-dirty")
        except Exception:
            # If git command fails, keep the base version
            pass

        return {"version": version, "full": full, "dirty": dirty}
    except Exception:
        # Any unexpected error falls back to default
        return default

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Check if any element (or character) contains a plus sign
        if any('+' in str(item) for item in pieces):
            return '.'
        return '+'
    except Exception:
        # If pieces is not iterable or any other error occurs, assume no plus
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Normalize inputs
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a list or tuple of command parts")

    # Build the full command
    full_cmd = list(commands) + list(args)

    # Merge environment variables if provided
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict of environment variables")
        env = {**os.environ, **env}
    else:
        env = os.environ

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except OSError as e:
        raise RuntimeError(f"Failed to execute command: {full_cmd}") from e

    # Handle errors
    if result.returncode != 0:
        stderr_msg = result.stderr.strip() if not hide_stderr else ""
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=stderr_msg
        )

    return result.stdout.strip() if result.stdout else ""

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    for param, name in [(validate_objects, 'validate_objects'),
                        (check_digests, 'check_digests'),
                        (show_warnings, 'show_warnings')]:
        if not isinstance(param, bool):
            raise TypeError(f"{name} must be a bool")

    # Ensure the root attribute exists and is iterable
    if not hasattr(self, 'root'):
        raise AttributeError("The object does not have a 'root' attribute to validate.")
    try:
        root_iter = iter(self.root)
    except TypeError:
        raise TypeError("The 'root' attribute must be an iterable of objects.")

    # Attempt to get hashlib from globals if available
    hashlib_module = globals().get('hashlib', None)

    num_objects = 0
    good_objects = 0

    for obj in root_iter:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                # Assume the object has a validate() method returning a bool
                is_valid = bool(getattr(obj, 'validate', lambda: False)())
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation failed for object {obj!r}: {e}")

        # Check digest if requested and the object passed previous validation
        if check_digests and is_valid:
            try:
                # Ensure the object has a path attribute
                path = getattr(obj, 'path', None)
                if path is None:
                    raise AttributeError("Object has no 'path' attribute for digest check.")
                # Compute digest if hashlib is available
                if hashlib_module is not None:
                    with open(path, 'rb') as f:
                        data = f.read()
                        digest = hashlib_module.sha256(data).hexdigest()
                    # Compare with stored digest if present
                    stored_digest = getattr(obj, 'digest', None)
                    if stored_digest is not None and digest != stored_digest:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for object {obj!r}.")
                else:
                    # hashlib not available; skip digest check
                    if show_warnings:
                        print(f"Warning: hashlib module not available; skipping digest check for {obj!r}.")
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check failed for object {obj!r}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Validate that the root path is set and is a string
    root = getattr(self, "root_path", None)
    if not root:
        raise ValueError("The 'root_path' attribute must be set and non-empty.")
    if not isinstance(root, str):
        raise TypeError("The 'root_path' attribute must be a string.")
    # Resolve to an absolute path
    root = os.path.abspath(root)
    # If the root exists, ensure it is a directory and empty
    if os.path.exists(root):
        if not os.path.isdir(root):
            raise ValueError(f"Root path '{root}' exists but is not a directory.")
        if os.listdir(root):
            raise ValueError(f"Root directory '{root}' is not empty; cannot initialize.")
    else:
        try:
            os.makedirs(root, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create root directory '{root}': {exc}") from exc
    # Create the .ocfl directory
    ocfl_dir = os.path.join(root, ".ocfl")
    try:
        os.makedirs(ocfl_dir, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Failed to create .ocfl directory '{ocfl_dir}': {exc}") from exc
    # Create the objects subdirectory
    objects_dir = os.path.join(ocfl_dir, "objects")
    try:
        os.makedirs(objects_dir, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Failed to create objects directory '{objects_dir}': {exc}") from exc
    # Create a default .ocflignore file to ignore hidden files
    ignore_file = os.path.join(objects_dir, ".ocflignore")
    if not os.path.exists(ignore_file):
        try:
            with open(ignore_file, "w", encoding="utf-8") as f:
                f.write("# Ignore hidden files\n.*\n")
        except Exception as exc:
            raise OSError(f"Failed to create ignore file '{ignore_file}': {exc}") from exc
    # Mark the instance as initialized
    self.initialized = True
    return None

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("version string cannot be empty")
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    original_len = len(version)
    try:
        num = int(version)
    except Exception as exc:
        raise ValueError("invalid numeric version") from exc
    num += 1
    new_str = str(num)
    if len(new_str) < original_len:
        new_str = new_str.zfill(original_len)
    return new_str

def validate_version_inventories(self, version_dirs):
        """
        Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, list):
            raise TypeError("version_dirs must be a list of directory names")
        if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
            raise AttributeError("root_inventory attribute missing or not a dict")

        # Store differences: {content_path: [list_of_version_numbers]}
        differences = {}

        for idx, vdir in enumerate(version_dirs, start=1):
            # Build path to the inventory file for this version
            inv_path = os.path.join(vdir, "inventory.json")

            # Check that the inventory file exists
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(
                    f"Missing inventory for version {idx} at expected path: {inv_path}"
                )

            # Load the inventory data
            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inv_data = json.load(f)
            except Exception as exc:
                raise ValueError(
                    f"Failed to read inventory for version {idx} at {inv_path}: {exc}"
                )

            # Inventory should be a mapping of content paths to digests
            if not isinstance(inv_data, dict):
                raise ValueError(
                    f"Inventory for version {idx} at {inv_path} is not a JSON object"
                )

            # Compare each digest with the root inventory
            for path, digest in inv_data.items():
                root_digest = self.root_inventory.get(path)
                if root_digest is None:
                    # New content not present in root; ignore for now
                    continue
                if digest != root_digest:
                    differences.setdefault(path, []).append(idx)

        # Store the differences on the instance for later use
        self.differences = differences
        return differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Look for a Namaste file named "0=*"
            namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
            if not namaste_files:
                return f"No Namaste file found in directory: {path}"
            # Check for presence of an "objects" subdirectory
            objects_dir = os.path.join(path, "objects")
            if os.path.isdir(objects_dir):
                return "root"
            else:
                return "object"
        return f"Unknown path type: {path}"
    except Exception as e:
        return f"Error determining path type: {e}"

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Recursive merge of two mapping nodes
    def merge_mapping_nodes(node1, node2):
        try:
            # Build a dict from node1's key string to (key_node, value_node)
            map1 = {k.value: (k, v) for k, v in node1.value}
            for k2, v2 in node2.value:
                key_str = k2.value
                if key_str in map1:
                    _, v1 = map1[key_str]
                    if is_mapping_node(v1) and is_mapping_node(v2):
                        merge_mapping_nodes(v1, v2)
                    else:
                        map1[key_str] = (k2, v2)
                else:
                    map1[key_str] = (k2, v2)
            node1.value = list(map1.values())
        except Exception:
            # In case of unexpected structure, fall back to last value
            node1.value = node2.value

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, value) tuples')

    merged_map = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            continue  # skip invalid entries
        key_node, val_node = item
        if not hasattr(key_node, 'value'):
            continue
        key_str = key_node.value
        if key_str in merged_map:
            _, existing_val = merged_map[key_str]
            if is_mapping_node(existing_val) and is_mapping_node(val_node):
                merge_mapping_nodes(existing_val, val_node)
            else:
                merged_map[key_str] = (key_node, val_node)
        else:
            merged_map[key_str] = (key_node, val_node)

    return list(merged_map.values())

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation of the input
    if parser is None:
        raise TypeError("parser cannot be None")
    # Check for typical attributes of an ArgumentParser
    if not hasattr(parser, "_actions") or not hasattr(parser, "add_argument"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # action.option_strings is a list of option strings for this action
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception as exc:
        # Wrap any unexpected exception in a RuntimeError with context
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # Validate that all provided arguments are strings
    if not all(isinstance(arg, str) for arg in unparsed_arguments):
        raise TypeError("All arguments must be strings")

    # Create a top-level parser with a subparsers container
    parser = argparse.ArgumentParser()
    # The dest name will hold the subparser name if one is used
    parser.add_subparsers(dest='subparser_name')

    try:
        # parse_known_args allows unknown arguments to be ignored, which is useful if
        # subparsers are defined elsewhere and we only want the top-level namespace.
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except SystemExit as exc:
        # argparse calls sys.exit on error, which raises SystemExit.
        # Convert this to a ValueError to avoid exiting the program.
        raise ValueError(f"Argument parsing failed: {exc}") from exc

    subparser_name = getattr(namespace, 'subparser_name', None)
    if subparser_name:
        return {subparser_name: namespace}
    else:
        return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic validation
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping names to ArgumentParser instances")

    parsed_namespaces = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        # Ensure the parser has the expected method
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Subparser '{name}' does not have a 'parse_known_args' method")
        try:
            ns, unknown = parser.parse_known_args(unparsed_arguments)
        except SystemExit as exc:
            # argparse uses SystemExit on parse errors; convert to ValueError for clarity
            raise ValueError(f"Error parsing arguments for subparser '{name}': {exc}") from exc
        parsed_namespaces[name] = ns
        unknown_sets.append(set(unknown))

    # Determine remaining arguments not claimed by any subparser
    if unknown_sets:
        remaining = [arg for arg in unparsed_arguments if all(arg in us for us in unknown_sets)]
    else:
        remaining = list(unparsed_arguments)

    return parsed_namespaces, remaining

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate keys.
    """
    # Basic validation
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    for idx, item in enumerate(nodes):
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError(f"Each item must be a tuple of (ScalarNode, value), got {item!r} at index {idx}")

    def is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map"

    def merge_mapping_nodes(target, source):
        """
        Merge source MappingNode into target MappingNode in place.
        """
        if not is_mapping(target) or not is_mapping(source):
            # If either is not a mapping, source wins
            return source

        # Build index for target keys
        target_keys = {}
        for i, (k_node, v_node) in enumerate(target.value):
            target_keys[k_node.value] = i

        for k_node, v_node in source.value:
            key = k_node.value
            if key in target_keys:
                idx = target_keys[key]
                existing_v_node = target.value[idx][1]
                # Merge recursively if both are mappings
                if is_mapping(existing_v_node) and is_mapping(v_node):
                    merged = merge_mapping_nodes(existing_v_node, v_node)
                    target.value[idx] = (k_node, merged)
                else:
                    # Last wins
                    target.value[idx] = (k_node, v_node)
            else:
                # Append new key-value pair
                target.value.append((k_node, v_node))
                target_keys[key] = len(target.value) - 1
        return target

    result_nodes = []
    key_index = {}  # maps key value to index in result_nodes

    for k_node, v_node in nodes:
        key = k_node.value
        if key in key_index:
            idx = key_index[key]
            existing_v_node = result_nodes[idx][1]
            if is_mapping(existing_v_node) and is_mapping(v_node):
                merged = merge_mapping_nodes(existing_v_node, v_node)
                result_nodes[idx] = (k_node, merged)
            else:
                # Last wins
                result_nodes[idx] = (k_node, v_node)
        else:
            result_nodes.append((k_node, v_node))
            key_index[key] = len(result_nodes) - 1

    return result_nodes

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation
    if parser is None:
        raise ValueError("parser cannot be None")
    # Check for typical argparse attributes
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        actions = parser._actions
    except Exception as exc:
        raise TypeError("Failed to access parser actions") from exc

    flags = []
    for action in actions:
        try:
            option_strings = getattr(action, "option_strings", [])
            if option_strings:
                flags.extend(option_strings)
        except Exception:
            # Skip actions that don't expose option_strings
            continue

    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    parser = argparse.ArgumentParser()
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        # Return a mapping with the global namespace. If subparsers are defined elsewhere,
        # they will be merged into this namespace; this function does not attempt to split
        # them because the subparser definitions are not known here.
        return {'global': namespace}
    except Exception as exc:
        raise ValueError(f"Argument parsing failed: {exc}") from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator that yields slices of the list
    def _generator():
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    result = {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError(f"Input must be an iterable of dictionaries, got {type(dicts).__name__}")
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element at index {idx} is not a dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float, complex)):
                raise TypeError(f"Value for key '{key}' is not a number, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if url is None:
        return None
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    result = url
    start = 0
    while True:
        open_brace = result.find('{', start)
        if open_brace == -1:
            break
        close_brace = result.find('}', open_brace + 1)
        if close_brace == -1:
            break
        key = result[open_brace + 1:close_brace]
        if key in url_args:
            value = str(url_args[key])
            result = result[:open_brace] + value + result[close_brace + 1:]
            start = open_brace + len(value)
        else:
            start = close_brace + 1
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        stripped = val.strip().lower()
        return stripped in ("none", "null", "nil")
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            flags.extend(action.option_strings)
        return ' '.join(flags)
    except Exception as e:
        raise ValueError(f"Error extracting flags: {e}") from e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate number
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")

    # Validate alphabet
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"alphabet element at index {idx} is not a string")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet symbols must be unique")

    base = len(alphabet)

    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Convert number to base representation
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    result = "".join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve subclasses of {cls.__name__}") from exc
    for sub in direct_subs:
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate entries.")
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("Alphabet elements must be single-character strings.")
    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Handle empty string
    if string == "":
        return 0

    result = 0
    for idx, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {idx} not found in alphabet.")
        result = result * base + char_to_value[ch]
    return result

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        # Remove leading and trailing single or double quotes
        return re.sub(r"^['\"]|['\"]$", "", name)
    except Exception:
        # If any unexpected error occurs, return the original value
        return name

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        # Accept pathlib.Path objects
        if hasattr(filename, "name"):
            filename = filename.name
        # Decode bytes if necessary
        if isinstance(filename, (bytes, bytearray)):
            try:
                filename = filename.decode()
            except Exception:
                return False
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename)
        if not ext:
            return False
        ext = ext.lower()
        supported_extensions = {
            ".txt", ".md", ".py", ".json", ".yaml", ".yml",
            ".csv", ".xml", ".html", ".htm", ".ini", ".conf",
            ".cfg", ".log"
        }
        return ext in supported_extensions
    except Exception:
        return False

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if not freq_str:
        raise ValueError("Frequency string is empty")
    if freq_str.lower() == "always":
        return None

    parts = freq_str.split()
    if len(parts) < 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    # The first part should be a number; the rest form the unit
    num_str = parts[0]
    unit_str = " ".join(parts[1:]).lower()

    try:
        # Allow integer or float values
        if '.' in num_str:
            number = float(num_str)
        else:
            number = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: '{num_str}'")

    # Map unit to timedelta keyword arguments
    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }

    if unit_str not in unit_map:
        raise ValueError(f"Unrecognized time unit in frequency: '{unit_str}'")

    kwargs = {unit_map[unit_str]: number}
    return datetime.timedelta(**kwargs)

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    # Validate input
    if find_paths is None:
        return []
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")

    result = []
    for path in iterator:
        if not isinstance(path, str):
            raise TypeError(f"Each find path must be a string, got {type(path).__name__}")
        # If the path contains a colon, treat it as an existing pattern and leave unchanged
        if ':' in path:
            result.append(path)
        else:
            # Escape any special glob characters? For simplicity, we just wrap the fragment
            # in a pattern that matches anywhere in the path.
            # If the fragment is empty, produce a pattern that matches any path.
            if path:
                pattern = f"sh:**/*{path}*/**"
            else:
                pattern = "sh:**/**"
            result.append(pattern)
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows environment
        if os.name != 'nt':
            return False
        # Git Bash sets OSTYPE to 'msys' or 'cygwin'
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True
        # Some Git Bash installations set MSYSTEM (e.g., MINGW64)
        if 'MSYSTEM' in os.environ:
            return True
        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # Ensure parent directories exist
    dirpath = os.path.dirname(config_filename)
    if dirpath:
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError as e:
            raise RuntimeError(f"Failed to create directories for {config_filename}: {e}") from e

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File {config_filename} already exists and overwrite is False")

    # Write the configuration file
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as e:
        raise RuntimeError(f"Failed to write configuration to {config_filename}: {e}") from e
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    try:
        var_name = matcher.group(1)
        default = matcher.group(2)
    except Exception as exc:
        raise ValueError("Invalid matcher object for environment variable resolution.") from exc

    value = os.getenv(var_name)
    if value is None:
        if default is not None:
            return default
        raise ValueError(f"Environment variable '{var_name}' not set and no default provided.")
    return value

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic input validation
    if graph is None:
        raise TypeError("graph must not be None")
    if not hasattr(graph, "triples"):
        raise TypeError("graph must have a triples method")
    if prop is None:
        raise ValueError("prop must not be None")
    if roots is not None and not isinstance(roots, set):
        raise TypeError("roots must be a set of nodes or None")

    children: Set["Node"] = set()
    parents: Set["Node"] = set()

    try:
        for child, _, parent in graph.triples((None, prop, None)):
            children.add(child)
            parents.add(parent)
    except Exception as exc:
        raise RuntimeError(f"Error iterating over graph triples: {exc}") from exc

    # Nodes that appear as parents but never as children are roots
    roots_set: Set["Node"] = parents - children

    # If a subset of roots was supplied, intersect with the computed set
    if roots is not None:
        roots_set = roots_set.intersection(roots)

    return roots_set

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            result = yaml.safe_dump(obj)
        else:
            result = yaml.safe_dump(obj, Dumper=dumper)
        # Ensure the result is a unicode string in Python 2 or a str in Python 3
        if isinstance(result, str):
            try:
                result = result.decode('utf-8')
            except Exception:
                pass
        return result
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, tuple):
        raise TypeError(f"shape must be a tuple, got {type(shape).__name__}")
    for idx, dim in enumerate(shape):
        if not isinstance(dim, int):
            raise TypeError(f"shape element at index {idx} must be an int, got {type(dim).__name__}")
        if dim < 0:
            raise ValueError(f"shape element at index {idx} must be non-negative, got {dim}")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {dtype}") from exc

    # Create the array
    try:
        return np.empty(shape, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape} and dtype {dtype}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    if x is None:
        raise TypeError("Input cannot be None")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be a number or array-like of numbers") from e
    mu = 0.2
    sigma = 0.1
    try:
        result = np.exp(-((arr - mu)**2) / (2 * sigma**2))
    except Exception as e:
        raise ValueError("Error computing Gaussian: " + str(e)) from e
    if np.isscalar(x):
        return float(result)
    return result

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re

    configs = {}
    error_records = []

    # Regular expression to find ${VAR} patterns
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_in_value(value):
        """Recursively resolve environment variables in strings."""
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env_in_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_in_value(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f"JSON decode error in file '{filename}': {e}"
                    record = logging.LogRecord('config_loader', logging.ERROR,
                                               filename, 0, msg, None, None)
                    error_records.append(record)
                    continue

            # Basic validation: configuration must be a dict
            if not isinstance(data, dict):
                msg = f"Configuration in file '{filename}' is not a JSON object (dict)."
                record = logging.LogRecord('config_loader', logging.ERROR,
                                           filename, 0, msg, None, None)
                error_records.append(record)
                continue

            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                # Merge overrides into data (shallow copy)
                merged = data.copy()
                merged.update(overrides)
                data = merged

            # Resolve environment variables if requested
            if resolve_env:
                data = _resolve_env_in_value(data)

            configs[filename] = data

        except FileNotFoundError:
            msg = f"Configuration file '{filename}' not found."
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       filename, 0, msg, None, None)
            error_records.append(record)
        except Exception as exc:
            # Catch-all for unexpected errors
            msg = f"Unexpected error loading file '{filename}': {exc}"
            record = logging.LogRecord('config_loader', logging.ERROR,
                                       filename, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :raises TypeError: If ``values`` is not an iterable of strings.
    :raises ValueError: If any element in ``values`` is not a string.
    :return: A new :class:`Bookmarks` instance containing the provided values.
    """
    # Basic validation of the input
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, got a single string")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable of strings, got {type(values).__name__}")

    cleaned = []
    for idx, v in enumerate(iterator):
        if not isinstance(v, str):
            raise ValueError(f"Bookmark at position {idx} is not a string (got {type(v).__name__})")
        cleaned.append(v)

    # Construct the Bookmarks instance.  The constructor is assumed to accept
    # an iterable of strings; if it expects a different signature, this
    # method may need to be adjusted accordingly.
    try:
        return cls(cleaned)
    except Exception as exc:
        # Wrap any unexpected constructor errors in a ValueError for clarity
        raise ValueError(f"Failed to create Bookmarks instance: {exc}") from exc

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # Check interface provision unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"{candidate!r} does not provide {iface!r}")
        except Exception as exc:
            errors.append(f"Error checking providedBy: {exc}")

    # Check required methods
    try:
        methods = iface.methods()
    except Exception:
        methods = []
    for name in methods:
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r} in {candidate!r}")
        else:
            attr = getattr(candidate, name)
            if not callable(attr):
                errors.append(f"Attribute {name!r} in {candidate!r} is not callable")

    # Check required attributes
    try:
        attrs = iface.attributes()
    except Exception:
        attrs = []
    for name in attrs:
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name!r} in {candidate!r}")

    # Raise collected errors if any
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("; ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Validate iface
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class, got {type(iface).__name__}")
    # Validate candidate
    if not isinstance(candidate, (type, object)):
        raise TypeError(f"candidate must be a class or instance, got {type(candidate).__name__}")
    # Determine attributes to check (exclude special/magic names)
    iface_attrs = [name for name in dir(iface) if not name.startswith('_')]
    missing = []
    for name in iface_attrs:
        try:
            if not hasattr(candidate, name):
                missing.append(name)
        except Exception:
            missing.append(name)
    if missing:
        if tentative:
            return False
        else:
            missing_str = ', '.join(missing)
            raise TypeError(f"Candidate {candidate} does not provide required attributes for iface {iface}: {missing_str}")
    return True

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Try using freq_buckets if available
        freq_buckets = getattr(self, '_freq_buckets', None) or getattr(self, 'freq_buckets', None)
        if isinstance(freq_buckets, dict) and freq_buckets:
            min_freq = min(freq_buckets.keys())
            bucket = freq_buckets[min_freq]
            key, value = bucket.popitem()
            # Remove from main data structures
            data_map = getattr(self, '_data', None) or getattr(self, 'data', None) or getattr(self, 'cache', None)
            if data_map is not None:
                data_map.pop(key, None)
            freq_map = getattr(self, '_freq', None) or getattr(self, 'freq', None)
            if freq_map is not None:
                freq_map.pop(key, None)
            # Clean up bucket if empty
            if not bucket:
                freq_buckets.pop(min_freq, None)
            return (key, value)
    except Exception:
        pass
    # Fallback: scan freq_map
    freq_map = getattr(self, '_freq', None) or

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is expected to store its items in an OrderedDict
    # named `_cache`, where the first item is the least recently used.
    if not hasattr(self, "_cache"):
        raise AttributeError("The cache object does not have a `_cache` attribute.")
    cache = getattr(self, "_cache")
    if not isinstance(cache, dict):
        raise TypeError("The `_cache` attribute must be a dictionary-like object.")
    try:
        # `popitem(last=False)` removes the first item (least recently used)
        key, value = cache.popitem(last=False)
    except KeyError:
        # The cache is empty
        raise KeyError("popitem(): dictionary is empty")
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = next(reversed(self.items()))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    # Remove the key from the dictionary
    self.pop(key)
    return key, value

def _create_converter(self) -> _converting._Converter:
        """
        Create the parameter style converter.

        Returns the parameter style converter (:class:`._converting._Converter`).
        """
        # Determine the parameter style from the instance attributes.
        # Prefer a dedicated attribute if present, otherwise fall back to a generic one.
        style = getattr(self, "_parameter_style", None)
        if style is None:
            style = getattr(self, "_style", None)

        # Validate the style value.
        if style is None:
            raise ValueError("Parameter style is not defined; cannot create converter.")
        if not isinstance(style, str):
            raise TypeError(f"Parameter style must be a string, got {type(style).__name__}")

        # Attempt to instantiate the converter, handling any unexpected errors.
        try:
            converter = _converting._Converter(style=style)
        except TypeError as exc:
            # If the constructor signature does not accept 'style', try a positional argument.
            try:
                converter = _converting._Converter(style)
            except Exception as exc2:
                raise RuntimeError("Failed to instantiate _converting._Converter with the provided style.") from exc2
        except Exception as exc:
            # Wrap any other exception in a RuntimeError for clarity.
            raise RuntimeError("An unexpected error occurred while creating the converter.") from exc

        return converter

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False
        # If request is a string
        if isinstance(request, str):
            return 'diaspora' in request.lower()
        # If request is a dict
        if isinstance(request, dict):
            # Check public_message
            if 'public_message' in request:
                msg = request['public_message']
                if isinstance(msg, str) and 'diaspora' in msg.lower():
                    return True
            # Check private_message
            if 'private_message' in request:
                msg = request['private_message']
                if isinstance(msg, str) and 'diaspora' in msg.lower():
                    return True
            # Check legacy_payload
            if 'legacy_payload' in request:
                payload = request['legacy_payload']
                if isinstance(payload, dict) and payload.get('type') == 'diaspora':
                    return True
            # Check type
            if request.get('type') == 'diaspora':
                return True
            # Check diaspora key
            if 'diaspora' in request:
                return True
            return False
        # If request is a list, tuple, or set
        if isinstance(request, (list, tuple, set)):
            for item in request:
                if identify_request(item):
                    return True
            return False
        # If request is an object with attributes
        if hasattr(request, 'public_message'):
            msg = getattr(request, 'public_message')
            if isinstance(msg, str) and 'diaspora' in msg.lower():
                return True
        if hasattr(request, 'private_message'):
            msg = getattr(request, 'private_message')
            if isinstance(msg, str) and 'diaspora' in msg.lower():
                return True
        if hasattr(request, 'legacy_payload'):
            payload = getattr(request, 'legacy_payload')
            if isinstance(payload, dict) and payload.get('type') == 'diaspora':
                return True
        if hasattr(request, 'type') and getattr(request, 'type') == 'diaspora':
            return True
        if hasattr(request, 'diaspora'):
            return True
        return False
    except Exception:
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # If request is a dictionary, look for typical Matrix keys
        if isinstance(request, dict):
            # Common Matrix request structure contains 'type' and 'content'
            if 'type' in request and 'content' in request:
                return True
            # Some Matrix requests may include room and sender identifiers
            if 'room_id' in request and 'sender' in request:
                return True
        else:
            # For non-dict objects, check for attributes that are typical of Matrix requests
            if hasattr(request, 'type') and hasattr(request, 'content'):
                return True
            if hasattr(request, 'room_id') and hasattr(request, 'sender'):
                return True
    except Exception:
        # Any unexpected error during inspection should result in False
        return False
    return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        # Must be a string
        if not isinstance(tag, str):
            return False
        # Non-empty
        if not tag:
            return False
        # Length limit (example: 30 characters)
        if len(tag) > 30:
            return False
        # Only lowercase letters, digits, and hyphens
        allowed_chars = set("abcdefghijklmnopqrstuvwxyz0123456789-")
        if any(ch not in allowed_chars for ch in tag):
            return False
        # Cannot start or end with a hyphen
        if tag[0] == '-' or tag[-1] == '-':
            return False
        # No consecutive hyphens
        if '--' in tag:
            return False
        return True
    except Exception:
        # In case of unexpected errors, return False
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element with iterable children") from exc

    result = {}
    for child in children:
        tag = getattr(child, "tag", None)
        if tag is None:
            continue  # skip elements without a tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    url = url.strip()
    if not url:
        raise ValueError("url cannot be empty")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Determine the document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    else:
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        document_path = document_path.strip()
        if not document_path:
            document_path = "/.well-known/nodeinfo"

    # Normalize URL and path to avoid double slashes
    if url.endswith("/"):
        url = url[:-1]
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Construct the full href to the NodeInfo document
    href = url + document_path

    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
