def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # Helper to import modules without top-level import statements
    json = __import__('json')
    ET = __import__('xml.etree.ElementTree', fromlist=['ElementTree'])

    # Try JSON parsing first
    try:
        data = json.loads(document)
        # Ensure expected keys exist
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        links = data.get('links', [])
        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except Exception:
        pass  # fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        # Helper to find elements ignoring namespaces
        def findall(tag):
            return root.findall(f".//{{*}}{tag}")

        subject_elem = findall('Subject')
        subject = subject_elem[0].text if subject_elem else None

        alias_elems = findall('Alias')
        aliases = [e.text for e in alias_elems if e.text]

        link_elems = findall('Link')
        links = []
        for e in link_elems:
            link = {}
            # Include all attributes of the Link element
            for k, v in e.attrib.items():
                link[k] = v
            # If the Link element contains text, include it as 'href' if not already present
            if e.text and 'href' not in link:
                link['href'] = e.text.strip()
            links.append(link)

        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except Exception as exc:
        raise ValueError(f"Failed to parse Diaspora webfinger: {exc}") from exc

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        if not isinstance(handle, str):
            raise ValueError("handle must be a string")
        handle = handle.strip()
        if '@' not in handle:
            raise ValueError("handle must contain '@'")
        user, domain = handle.split('@', 1)
        if not user or not domain:
            raise ValueError("handle must be in the form user@domain")
        resource = f'acct:{handle}'
        import urllib.parse
        import urllib.request
        import json
        query = urllib.parse.quote(resource, safe='')
        url = f'https://{domain}/.well-known/webfinger?resource={query}'
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return {}
            data = resp.read().decode('utf-8')
            return json.loads(data)
    except Exception:
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Basic validation
        if not isinstance(url, str):
            raise ValueError("url must be a string")
        if not isinstance(method, str):
            raise ValueError("method must be a string")
        if not isinstance(timeout, (int, float)) or timeout <= 0:
            raise ValueError("timeout must be a positive number")
        if not isinstance(data, (dict, bytes)) and not hasattr(data, "read"):
            raise ValueError("data must be a dict, bytes, or file-like object")

        # Prepare request kwargs
        req_kwargs = kwargs.copy()
        req_kwargs["data"] = data
        req_kwargs["timeout"] = timeout

        # Perform the request
        response = requests.request(method, url, **req_kwargs)
        return (response.status_code, None)
    except Exception as e:
        # Return None for status code and the exception instance
        return (None, e)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    for k in keys:
        if not isinstance(k, str):
            raise TypeError("all keys must be strings")
    chain = [key] + list(keys)
    current = dic
    for k in chain[:-1]:
        if k not in current or not isinstance(current[k], dict):
            current[k] = {}
        current = current[k]
    current[chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the directories specified by `settings_dirs`.
    If `spec_option` is provided, it is treated as a glob pattern (e.g., '*.ini') and only
    files matching the pattern are returned. Directories that do not exist or are not
    accessible are silently skipped. Invalid input types raise a ValueError.
    """
    import os
    import fnmatch

    # Validate inputs
    if not isinstance(settings_dirs, (list, tuple)):
        raise ValueError("settings_dirs must be a list or tuple of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string or None")

    file_list = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            continue  # skip non-string entries
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option is None or spec_option == "":
                        file_list.append(full_path)
                    else:
                        if fnmatch.fnmatch(entry, spec_option):
                            file_list.append(full_path)
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue
    return file_list

