def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Ensure a file path was provided
        if yaml_file is None:
            raise ValueError("yaml_file must be a valid file path")

        # Import yaml and the custom exception only when needed
        try:
            import yaml
        except ImportError as exc:
            raise ImportError("PyYAML is required to load YAML files") from exc

        # Load the YAML file
        try:
            with open(yaml_file, "r", encoding="utf-8") as fh:
                data = yaml.safe_load(fh)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}") from exc

        # The YAML file must contain a mapping (dictionary)
        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file '{yaml_file}' does not contain a mapping")

        # Determine required fields; subclasses may override this attribute
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        if not isinstance(required_fields, (list, tuple)):
            raise IRValidatorException("REQUIRED_FIELDS must be a list or tuple of field names")

        # Check for missing required fields
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in '{yaml_file}': {', '.join(missing)}"
            )

        return data

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    The method expects `parser_dict` to be a dictionary that may contain an
    ``include`` key whose value is a list of group names.  Each group name
    refers to a dictionary stored in ``self._groups`` (or ``self.groups`` if
    the former is not present).  The contents of the referenced groups are
    merged into ``parser_dict`` in place.  Nested ``include`` directives are
    resolved recursively.  Circular references raise a ``ValueError``.
    """
    # Basic validation
    if not isinstance(parser_dict, dict):
        raise TypeError(f"_include_groups expects a dict, got {type(parser_dict).__name__}")

    # Retrieve and remove the include directive if present
    include = parser_dict.pop("include", None)
    if include is None:
        return  # nothing to do

    if not isinstance(include, (list, tuple)):
        raise TypeError(f"The 'include' directive must be a list or tuple, got {type(include).__name__}")

    # Groups mapping – fall back to an empty dict if not defined
    groups = getattr(self, "_groups", getattr(self, "groups", {}))
    if not isinstance(groups, dict):
        raise TypeError(f"Groups container must be a dict, got {type(groups).__name__}")

    visited = set()  # to detect circular includes

    def _merge_dicts(dest, src):
        """
        Recursively merge `src` into `dest`.  Keys in `src` override those
        in `dest` unless both values are dictionaries, in which case they
        are merged recursively.
        """
        for key, value in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(value, dict):
                _merge_dicts(dest[key], value)
            else:
                dest[key] = value

    def _resolve_group(name):
        if name in visited:
            raise ValueError(f"Circular include detected for group '{name}'")
        visited.add(name)

        group_def = groups.get(name)
        if group_def is None:
            raise KeyError(f"Included group '{name}' not found in self._groups")

        if not isinstance(group_def, dict):
            raise TypeError(f"Group '{name}' must be a dict, got {type(group_def).__name__}")

        # Work on a shallow copy to avoid mutating the original group definition
        group_copy = dict(group_def)

        # Resolve nested includes within the group
        nested_include = group_copy.pop("include", None)
        if nested_include is not None:
            if not isinstance(nested_include, (list, tuple)):
                raise TypeError(f"Nested 'include' in group '{name}' must be a list or tuple")
            for nested_name in nested_include:
                _resolve_group(nested_name)

        # Merge the resolved group into the main parser_dict
        _merge_dicts(parser_dict, group_copy)

    # Resolve all top‑level includes
    for group_name in include:
        if not isinstance(group_name, str):
            raise TypeError(f"Group name must be a string, got {type(group_name).__name__}")
        _resolve_group(group_name)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Retrieve the spec; it may be a dict or a list of (name, spec) tuples
        spec = getattr(self, "spec", None)
        if spec is None:
            return defaults

        # Helper to extract default from a spec entry
        def _extract_default(name, entry):
            # If entry is a dict, look for 'default'
            if isinstance(entry, dict):
                if "default" in entry:
                    return entry["default"]
            # If entry is not a dict, treat it as the default value itself
            return entry

        # Handle dict spec
        if isinstance(spec, dict):
            for name, entry in spec.items():
                if entry is None:
                    continue
                default = _extract_default(name, entry)
                if default is not None:
                    defaults[name] = default
                else:
                    # Fallback to other sources if available
                    if hasattr(self, "defaults") and isinstance(self.defaults, dict):
                        if name in self.defaults:
                            defaults[name] = self.defaults[name]
                    elif hasattr(self, "config") and isinstance(self.config, dict):
                        if name in self.config:
                            defaults[name] = self.config[name]
        # Handle list/tuple spec
        elif isinstance(spec, (list, tuple)):
            for item in spec:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    name, entry = item
                    default = _extract_default(name, entry)
                    if default is not None:
                        defaults[name] = default
                    else:
                        if hasattr(self, "defaults") and isinstance(self.defaults, dict):
                            if name in self.defaults:
                                defaults[name] = self.defaults[name]
                        elif hasattr(self, "config") and isinstance(self.config, dict):
                            if name in self.config:
                                defaults[name] = self.config[name]
                else:
                    # Skip malformed entries
                    continue
        else:
            # Unsupported spec type; raise a clear error
            raise TypeError(f"Unsupported spec type: {type(spec).__name__}")

        return defaults
    except Exception as exc:
        # Wrap any exception to provide context
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    try:
        # Mapping of deprecated option names to their replacements
        deprecated_map = {
            'old_option': 'new_option',
            'legacy_mode': 'mode',
            'use_legacy': 'use_new',
        }
        return deprecated_map
    except Exception:
        # In case of any unexpected error, return an empty mapping
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure the inputs are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Define patterns that indicate a deprecated argument.
    # This can be extended or replaced by a more sophisticated check if needed.
    deprecated_prefixes = ("old_", "legacy_", "deprecated_")

    # Collect deprecated keys from both sources
    deprecated_keys = []

    for key in cli_args:
        if any(key.startswith(prefix) for prefix in deprecated_prefixes):
            deprecated_keys.append(key)

    for key in answer_file_args:
        if any(key.startswith(prefix) for prefix in deprecated_prefixes):
            deprecated_keys.append(key)

    # Print a warning for each deprecated argument found
    for key in deprecated_keys:
        try:
            print(f"Warning: Argument '{key}' is deprecated and may be removed in future releases.")
        except Exception:
            # If printing fails for some reason, silently ignore
            pass

    # Return the list of deprecated keys for potential further handling
    return deprecated_keys

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not command_name:
        raise ValueError("command_name cannot be empty")

    # Retrieve the parser for the given command
    try:
        parser = self.parsers[command_name]
    except AttributeError:
        raise AttributeError("The object does not have a 'parsers' attribute")
    except KeyError:
        raise ValueError(f"Unknown command: {command_name}")

    # Collect option strings from the parser's actions
    options = []
    for action in getattr(parser, "_actions", []):
        # Skip positional arguments (no option strings)
        if not getattr(action, "option_strings", []):
            continue
        # Add each option string separately
        for opt in action.option_strings:
            if opt not in options:
                options.append(opt)

    return options

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    try:
        if args is None:
            return silent
        # Handle dictionary input: keys with None, False, or empty string values are considered silent
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value is False or value == '':
                    silent.append(key)
        # Handle list or tuple input
        elif isinstance(args, (list, tuple)):
            for item in args:
                # If item is a (name, value) tuple, treat it like a dict entry
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if value is None or value is False or value == '':
                        silent.append(name)
                # If item is a string, consider names starting with '_' or 'silent_' as silent
                elif isinstance(item, str):
                    if item.startswith('_') or item.startswith('silent_'):
                        silent.append(item)
                # Other types are ignored
        # Other types are ignored
    except Exception:
        # In case of any error, return an empty list
        return []
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []
        # Normalize args to a dict for easier lookup
        if isinstance(args, dict):
            arg_dict = args
        else:
            # If args is a list of tuples or similar, convert to dict
            try:
                arg_dict = dict(args)
            except Exception:
                arg_dict = {}

        for opt in options_spec:
            # Skip if no required_when key
            if 'required_when' not in opt:
                continue

            condition = opt['required_when']
            # If condition is callable, evaluate it
            if callable(condition):
                try:
                    if condition(arg_dict, command_name):
                        required.append(opt.get('name'))
                except Exception:
                    # If callable fails, skip this option
                    continue
                continue

            # If condition is a dict, treat as key-value pairs that must match
            if isinstance(condition, dict):
                match = True
                for key, val in condition.items():
                    if key not in arg_dict:
                        match = False
                        break
                    # If val is None, just check presence
                    if val is not None and arg_dict[key] != val:
                        match = False
                        break
                if match:
                    required.append(opt.get('name'))
                continue

            # If condition is a string, try simple parsing: "opt==value" or "opt"
            if isinstance(condition, str):
                cond = condition.strip()
                if '==' in cond:
                    key, val = [c.strip() for c in cond.split('==', 1)]
                    if key in arg_dict and str(arg_dict[key]) == val:
                        required.append(opt.get('name'))
                else:
                    # Just check presence
                    if cond in arg_dict:
                        required.append(opt.get('name'))
                continue

            # Unsupported condition type; ignore
        return required

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is not None
    if args is None:
        raise TypeError("args cannot be None")

    # Determine if args is a mapping (e.g., dict) or an iterable of values
    is_mapping = hasattr(args, "items")
    if is_mapping:
        iterable = args.items()
    else:
        try:
            iterable = enumerate(args)
        except TypeError:
            # Not iterable, treat as a single value
            iterable = [(None, args)]

    # Retrieve min and max bounds from the instance, if they exist
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    # If either bound is missing, skip validation
    if min_val is None or max_val is None:
        return True

    # Validate each argument value
    for key, value in iterable:
        if value is None:
            continue
        try:
            if not (min_val <= value <= max_val):
                raise ValueError(
                    f"Argument {key} with value {value} is out of bounds "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument {key} with value {value} is not comparable to min/max"
            )

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    try:
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")
    except Exception as exc:
        raise ValueError(f"Invalid arguments for create_complex_argumet_type: {exc}") from exc

    # Define a simple container class for the complex type
    class ComplexArgumentType:
        __slots__ = ("subcommand", "type_name", "option_name", "spec_option")

        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def __repr__(self):
            return (
                f"ComplexArgumentType(subcommand={self.subcommand!r}, "
                f"type_name={self.type_name!r}, option_name={self.option_name!r}, "
                f"spec_option={self.spec_option!r})"
            )

    # Create and return the complex type instance
    try:
        complex_type = ComplexArgumentType(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

    return complex_type

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: dict containing 'returncode', 'stdout', and 'stderr' from the
        ansible-playbook execution.
    """
    # Validate inputs
    if ir_workspace is None or ir_plugin is None:
        raise ValueError("Both ir_workspace and ir_plugin must be provided.")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string.")
    try:
        import os
        if not os.path.isfile(playbook_path):
            raise FileNotFoundError(f"Playbook not found: {playbook_path}")
    except Exception as exc:
        raise RuntimeError(f"Error validating playbook path: {exc}") from exc

    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer.")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dictionary.")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dictionary.")

    # Build command
    cmd = ["ansible-playbook", playbook_path]
    if verbose:
        cmd.append("-" + "v" * verbose)

    if extra_vars:
        import json
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    if ansible_args:
        for key, value in ansible_args.items():
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Execute command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except OSError as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr
    }

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings. This method attempts to convert
    string values to bool, None, int, float, or list (comma separated) where
    appropriate. Nested dictionaries and lists are handled recursively.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dict of arguments to be converted.
    :raises TypeError: If values_dict is not a dictionary.
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    def _convert_value(val):
        # Recursively convert nested structures
        if isinstance(val, dict):
            for k, v in val.items():
                val[k] = _convert_value(v)
            return val
        if isinstance(val, list):
            return [_convert_value(item) for item in val]

        # Only attempt conversion for strings
        if not isinstance(val, str):
            return val

        s = val.strip()

        # Boolean conversion
        lower = s.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False

        # None conversion
        if lower == "none":
            return None

        # Integer conversion
        if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
            try:
                return int(s)
            except ValueError:
                pass

        # Float conversion
        try:
            if "." in s or "e" in s.lower():
                return float(s)
        except ValueError:
            pass

        # List conversion (comma separated)
        if "," in s:
            parts = [p.strip() for p in s.split(",")]
            return [_convert_value(part) for part in parts]

        # Default: return the original string
        return s

    # Apply conversion to each top-level key
    for key in list(values_dict.keys()):
        values_dict[key] = _convert_value(values_dict[key])

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path

    def _flatten_dict(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten_dict(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Resolve path
    try:
        p = Path(plugin_dir)
    except Exception as e:
        raise ValueError(f"Invalid plugin_dir path: {plugin_dir}") from e

    if not p.is_dir():
        raise ValueError(f"plugin_dir is not a directory: {plugin_dir}")

    # Find spec file
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        candidate = p / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    try:
        if spec_file.suffix in {'.yaml', '.yml'}:
            try:
                import yaml
            except ImportError as e:
                raise ImportError("PyYAML is required to parse YAML plugin specs") from e
            with spec_file.open('r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        else:  # .json
            import json
            with spec_file.open('r', encoding='utf-8') as f:
                data = json.load(f)
    except Exception as e:
        raise ValueError(f"Failed to parse plugin spec file {spec_file}: {e}") from e

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec must be a mapping, got {type(data).__name__}")

    return _flatten_dict(data)
